import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"UI Revamp v0 — Cutover Status","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/prd/ui-revamp-v0-cutover-status.md","filePath":"architecture/prd/ui-revamp-v0-cutover-status.md","lastUpdated":1780254295000}'),r={name:"architecture/prd/ui-revamp-v0-cutover-status.md"};function d(n,e,i,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="ui-revamp-v0-—-cutover-status" tabindex="-1">UI Revamp v0 — Cutover Status <a class="header-anchor" href="#ui-revamp-v0-—-cutover-status" aria-label="Permalink to &quot;UI Revamp v0 — Cutover Status&quot;">​</a></h1><p>Closes out the cutover series that landed the locked v0 surfaces from <a href="./ui-revamp-v0"><code>ui-revamp-v0.md</code></a> and <a href="./ui-revamp-v0-scaffold"><code>ui-revamp-v0-scaffold.md</code></a> into <code>desktop/soma</code>. Captures what&#39;s done, what&#39;s still open, and the gap most worth fixing before this work hardens — automated tests.</p><h2 id="what-landed" tabindex="-1">What landed <a class="header-anchor" href="#what-landed" aria-label="Permalink to &quot;What landed&quot;">​</a></h2><p>Ten PRs, each a focused chunk. Listed in merge order.</p><table tabindex="0"><thead><tr><th>PR</th><th>Cutover</th><th>Scope</th></tr></thead><tbody><tr><td><a href="https://github.com/stephane-segning/soma/pull/71" target="_blank" rel="noreferrer">#71</a></td><td>1</td><td>Tabbed Space settings shell (General · Members · Bots · Assistant · Sharing · Danger). Bots tab UI wired to a stub hook; capability issuance throws until 1b.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/72" target="_blank" rel="noreferrer">#72</a></td><td>2</td><td>Replace renderer <code>SpacesRail</code> with <code>@soma/ui</code> rail. Bundles a P0 hotfix mounting <code>SomaIntlProvider</code> at the renderer root — Cutover 1 had shipped <code>useT()</code>-using components that would have crashed at first render of the Bots add panel.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/73" target="_blank" rel="noreferrer">#73</a></td><td>3</td><td>Add a Jump-to-page <code>TreePopover</code> trigger to <code>AsideNavigation</code>. Floating-UI anchored under the header, populated from <code>useSpacesQuery</code>. The existing DnD <code>PageTree</code> stays — the popover is a complementary quick-switch, not a replacement.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/74" target="_blank" rel="noreferrer">#74</a></td><td>4</td><td>Swap <code>CommandPaletteShell</code> from <code>react-cmdk</code> to <code>@soma/ui</code>&#39;s <code>CommandPalette</code>. Sections Recent · Spaces · Documents · Commands. Adds an <code>onQueryChange</code> prop to the @soma/ui component so host apps can pipe debounced queries into an external search service. Drops <code>react-cmdk</code> from <code>desktop/soma</code>.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/75" target="_blank" rel="noreferrer">#75</a></td><td>5a</td><td>TipTap bubble menu renders <code>SelectionBubble</code> instead of the bespoke <code>FormatToolbar</code>. Wires bold/italic/underline/strike/code/link/highlight + block-style dropdown (replacing the rotate button). Ask AI chip routes to the existing quick-action panel handler — replaced again in 5d.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/76" target="_blank" rel="noreferrer">#76</a></td><td>5b</td><td>TipTap slash menu renders <code>SlashMenu</code>. Adds <code>captureScope: &quot;container&quot; | &quot;window&quot;</code> to the @soma/ui component so editor surfaces can listen for keyboard events while focus stays in the contenteditable. Renames the renderer command interface to require <code>section: SlashMenuSection</code> + optional <code>icon</code> + <code>shortcut</code>. Reserves a fixed icon slot so undefined-icon rows stay aligned.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/77" target="_blank" rel="noreferrer">#77</a></td><td>5c</td><td>TipTap mention picker renders <code>MentionPicker</code>. Extends <code>MentionSectionKind</code> with <code>&quot;spaces&quot;</code> so soma&#39;s <code>%</code> provider can render. Same <code>captureScope</code> pattern as SlashMenu. <code>MentionProvider</code> gains a required <code>section</code> field.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/78" target="_blank" rel="noreferrer">#78</a></td><td>5d</td><td>Mount <code>NodeAIRegistryExtension</code> in the default extension stack. New <code>createDefaultAIRegistry({ editor, onQuickAction })</code> factory bridges the legacy <code>onQuickAction</code> callback into the locked registry contract — explain/expand/research register across every text-bearing block type. <code>ContextualMenu</code> renders <code>SelectionAIBar</code> (replacing <code>QuickActionPanel</code>) when Ask AI fires.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/79" target="_blank" rel="noreferrer">#79</a></td><td>5e</td><td>ActionMenu chrome refresh. Drag-handle menu uses <code>glass-panel shadow-elevated</code>. New <code>HandleButton</code> helper standardises the buttons; <code>onClick</code> keyboard-accessible everywhere. Drag-handle <code>&lt;div&gt;</code> gets an <code>aria-label</code>. Rotate tooltip routes through <code>useT</code> with localized block names.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/pull/80" target="_blank" rel="noreferrer">#80</a></td><td>1b</td><td>End-to-end wiring of <code>issueIssuerCapability</code> from the Bots tab&#39;s Add form through IPC + RTK Query to the daemon. Fixes a unit mismatch caught in review — Rust treats <code>expires_at</code> as epoch seconds, JS callers stay in ms; conversion lives at the daemon-client boundary. <code>expires_at == 0</code> is the daemon&#39;s no-expiry sentinel; the form&#39;s &quot;Never&quot; toggle now flows through correctly.</td></tr></tbody></table><p>Each cutover landed with a typecheck pass on both <code>pnpm --filter soma run typecheck:web</code> and (for backend-touching changes) <code>typecheck:node</code>. The pre-existing <code>pnpm --filter @soma/editor run typecheck</code> failure (<code>error TS2209: project root is ambiguous</code>) was fixed in <a href="https://github.com/stephane-segning/soma/pull/83" target="_blank" rel="noreferrer">#83</a> as part of the NodeAIRegistry-test PR — <code>tsconfig.json</code> gained <code>&quot;rootDir&quot;: &quot;./src&quot;</code> and the spurious <code>@soma/ui/*</code> path alias was dropped. All four packages now typecheck cleanly on <code>main</code>.</p><h2 id="open-gaps" tabindex="-1">Open gaps <a class="header-anchor" href="#open-gaps" aria-label="Permalink to &quot;Open gaps&quot;">​</a></h2><h3 id="daemon-side-rust" tabindex="-1">Daemon-side (Rust) <a class="header-anchor" href="#daemon-side-rust" aria-label="Permalink to &quot;Daemon-side (Rust)&quot;">​</a></h3><p>These three unblock the next round of UI work.</p><ul><li><s><strong><code>SomaHandle.list_space_bots</code></strong> — no napi method yet. The Bots tab&#39;s list view is empty until this lands. <code>useSpaceBots</code> is shaped to drop in a <code>useListSpaceBotsQuery</code> call without further component changes.</s> <strong>Landed in <a href="https://github.com/stephane-segning/soma/pull/84" target="_blank" rel="noreferrer">#84</a></strong> — <code>DaemonHandle::list_space_bots</code> filters memberships server-side to <code>role == &quot;bot&quot;</code>, exposed through napi as <code>listSpaceBots</code>, IPC channel <code>spaces_list_bots</code>, RTK Query <code>useListSpaceBotsQuery</code>. The hook now hydrates <code>bots</code> from the daemon. Bot rows are mapped onto the <code>@soma/ui</code> <code>Bot</code> shape with a placeholder <code>alias = &quot;bot-&lt;peerSuffix&gt;&quot;</code> and <code>status = &quot;active&quot;</code> until the schema extensions below land.</li><li><s><strong>Capability record schema</strong> — the <code>IssueIssuerCapability</code> daemon path stores peer id + expiry only. The Bots form captures <code>alias</code> + <code>scopeIds[]</code> and currently throws them away.</s> <strong>Alias half landed in <a href="https://github.com/stephane-segning/soma/pull/85" target="_blank" rel="noreferrer">#85</a></strong> — new migration adds <code>issuer_capabilities.alias</code>, plumbed end-to-end through <code>IssueIssuerCapabilityInput</code> → napi → IPC → RTK Query → <code>useSpaceBots.addBot</code>. The list view shows the operator-typed alias instead of the synthesised <code>bot-&lt;peerSuffix&gt;</code> placeholder (which now only fires for legacy rows / blank inputs). <strong><code>scopeIds[]</code> storage half landed in <a href="https://github.com/stephane-segning/soma/pull/92" target="_blank" rel="noreferrer">#92</a></strong> — new migration adds <code>issuer_capabilities.scopes</code> (nullable TEXT, JSON-encoded array), plumbed end-to-end through storage → membership → daemon → napi → IPC → RTK Query → <code>useSpaceBots.addBot</code> (forwards <code>input.scopeIds</code> as <code>scopes</code>). <strong>Runtime enforcement landed</strong> — <code>membership::ensure_can_issue_membership</code> now reads <code>scopes</code> from the local row and rejects non-matching capabilities; empty scopes (<code>[]</code>) remain unrestricted for backward compat with pre-#92 rows. The only recognised scope in v0 is <code>&quot;issue:membership&quot;</code>. Scopes are enforced locally only (option B) — the signed proto does not yet carry a scopes field; that is a future hardening step (option A).</li><li><strong>Bot status event stream</strong> — once bots are listed, the UI wants to reflect handshake state (<code>pending</code> / <code>active</code> / <code>expired</code>) without polling. A daemon event stream (analogous to the existing <code>agent-events</code>) would let the renderer subscribe. <ul><li><strong>Foundation landed in <a href="https://github.com/stephane-segning/soma/pull/86" target="_blank" rel="noreferrer">#86</a></strong>: migration adds <code>issuer_capabilities.status TEXT NOT NULL DEFAULT &#39;active&#39;</code>; daemon derives <code>expired</code> from <code>expires_at</code> at read time; new <code>BotStatus</code> <code>&quot;expired&quot;</code> variant on <code>@soma/ui</code> with a <code>warning</code>-tone Pill.</li><li><strong>Event stream landed in <a href="https://github.com/stephane-segning/soma/pull/87" target="_blank" rel="noreferrer">#87</a></strong>: new <code>BotStatusChangedEvent</code> proto variant on <code>DaemonEvent</code>; daemon publishes on every issuance; napi + soma main translate to a <code>space-changed</code> domain event keyed by <code>(spaceId)</code>, which invalidates the <code>SpaceMembers/&lt;spaceId&gt;</code> RTK cache tag so the Bots-tab list refetches without polling.</li><li><strong>Handshake protocol landed in <a href="https://github.com/stephane-segning/soma/pull/88" target="_blank" rel="noreferrer">#88</a></strong>: new <code>/soma/issuer-offer/1</code> libp2p request_response protocol. Owner issuance now writes <code>pending</code> to storage and dispatches the signed capability to the delegate peer; the delegate auto-ACKs via the codec layer; on receipt the owner transitions to <code>active</code> (or <code>failed</code> on libp2p send error / timeout) and publishes a follow-up <code>BotStatusChangedEvent</code>. The <code>Bots</code> tab pill now reflects the real handshake outcome end-to-end. Capability-validation on the delegate side is deferred to a separate PR (the codec accepts any well-formed proto and auto-ACKs).</li></ul></li></ul><h3 id="renderer-follow-ups-typescript-only" tabindex="-1">Renderer follow-ups (TypeScript only) <a class="header-anchor" href="#renderer-follow-ups-typescript-only" aria-label="Permalink to &quot;Renderer follow-ups (TypeScript only)&quot;">​</a></h3><p>These can land independently of daemon work.</p><ul><li><s><strong><code>@mention</code> bots provider</strong> — once <code>list_space_bots</code> ships, register a fourth <code>MentionProvider</code> with <code>section: &quot;bots&quot;</code> so <code>@bot:alias</code> resolves inline in the editor and chat composers.</s> <strong>Landed in <a href="https://github.com/stephane-segning/soma/pull/99" target="_blank" rel="noreferrer">#99</a></strong> — new provider in <code>space-page/mentions.ts</code>. The trigger char is <code>!</code> (TipTap&#39;s Suggestion plugin is one-char-per-extension and <code>@</code> was already taken by members), so bots are addressed as <code>!bot-alias</code> in the editor — note the deliberate departure from the originally-planned <code>@bot:alias</code> syntax. The picker section was the existing <code>&quot;bots&quot;</code> kind added in cutover 5c. <strong>Deep-link fix in <a href="https://github.com/stephane-segning/soma/pull/101" target="_blank" rel="noreferrer">#101</a></strong> — the original href pointed at a non-existent <code>/spaces/:id/settings/bots</code> route; replaced with <code>/spaces/:id/settings?tab=bots&amp;peerId=...</code> and <code>space-settings.tsx</code> now reads the query string to pre-select the Bots tab + highlight the row.</li><li><s><strong>Block-level AI dispatch</strong> — Cutover 5e didn&#39;t wire the action-menu&#39;s AI affordance. The plan is: click AI on the drag handle → set the block as a <code>NodeSelection</code> → <code>ContextualMenu</code> renders <code>SelectionAIBar</code> with <code>surface: &quot;node&quot;</code>. The registry and the UI both already understand the node surface; only the trigger is missing.</s> <strong>Landed in <a href="https://github.com/stephane-segning/soma/pull/95" target="_blank" rel="noreferrer">#95</a></strong> — new <code>Star</code> AI button on the drag-handle menu, gated on <code>onQuickAction</code> being wired; click sets <code>NodeSelection</code> and opens a second <code>SelectionAIBar</code> instance anchored at the handle position. <code>createDefaultAIRegistry</code> actions now register on <code>[&quot;selection&quot;, &quot;node&quot;]</code> so the same catalog appears in both bars. Review caught a latent bug (selection-surface <code>action.run()</code> had never forwarded <code>metadata.from/.to</code>, so even the existing bubble flow was bailing out of <code>dispatchAndInsert</code>); fixed alongside.</li><li><s><strong>Editor-command icons</strong> — <code>desktop/soma/.../space-page/editor-commands.ts</code> registers four slash commands (<code>new-sub-page</code>, <code>insert-image</code>, <code>insert-file</code>, <code>link-to-page</code>) without icons. SlashMenu now reserves the slot so alignment is fine, but the rows look bare next to the default commands. Rename to <code>.tsx</code> and pass <code>react-feather</code> icons.</s> <strong>Landed in <a href="https://github.com/stephane-segning/soma/pull/93" target="_blank" rel="noreferrer">#93</a></strong> — <code>editor-commands.ts</code> → <code>.tsx</code> with <code>&lt;File /&gt;</code>, <code>&lt;Image /&gt;</code>, <code>&lt;Paperclip /&gt;</code>, <code>&lt;Link2 /&gt;</code> aliased to <code>FileIcon</code>/<code>ImageIcon</code> to avoid shadowing the DOM <code>File</code>/<code>Image</code> types (a real bug Gemini caught).</li><li><s><strong>Recent-pages slice</strong> — <code>TreePopover</code> and <code>CommandPalette</code> both surface a Recent section that&#39;s empty in v0. Add a small redux slice keyed by <code>(spaceId, pageId, openedAt)</code>, capped at ~10 entries, hydrated from disk.</s> <strong>Landed in <a href="https://github.com/stephane-segning/soma/pull/100" target="_blank" rel="noreferrer">#100</a></strong> — new <code>recentPages</code> slice + <code>recordPageOpened</code> action; <code>openedAt</code> flows in from the <code>useEffect</code> payload (not synthesised in the reducer, per review feedback) and persistence is a listener middleware (not a reducer side effect). <code>TreePopover</code> filters to the current space; <code>CommandPalette</code> shows the cross-space Recent list.</li><li><strong>Default-expiry policy</strong> — <strong>landed (#97).</strong> The daemon now enforces a 180-day maximum issuable lifetime (<code>MAX_ISSUER_CAPABILITY_LIFETIME_SECS</code> in <code>backend/crates/daemon/src/handle/issuer.rs</code>); the renderer&#39;s &quot;Never&quot; toggle still passes <code>0</code> and the daemon translates it to <code>now + 180 days</code> server-side. Explicit expiries above the ceiling are rejected with <code>expires_at exceeds maximum issuer capability lifetime</code>. Follow-up: surface &quot;Expires in up to 180 days&quot; near the toggle in <code>CapabilityForm</code> so operators aren&#39;t surprised by the bounded lifetime.</li></ul><h3 id="locked-soma-ui-surfaces-that-ship-inert-in-soma-today" tabindex="-1">Locked @soma/ui surfaces that ship inert in soma today <a class="header-anchor" href="#locked-soma-ui-surfaces-that-ship-inert-in-soma-today" aria-label="Permalink to &quot;Locked @soma/ui surfaces that ship inert in soma today&quot;">​</a></h3><ul><li><code>SelectionBubble</code>&#39;s <strong>Comment</strong> + <strong>More</strong> buttons — not wired (the menu component&#39;s props are optional; the buttons hide when their callbacks aren&#39;t passed).</li><li><s><code>SelectionBubble</code>&#39;s <strong>Highlight</strong></s> — <strong>landed</strong> (<code>feat(editor): wire Highlight extension into SelectionBubble</code>). <code>@tiptap/extension-highlight</code> added to the extension stack (<code>multicolor: false</code>); <code>onToggleHighlight</code> and <code>highlight</code> active prop wired in <code>ContextualMenu</code>.</li><li><code>BackendSwitcher</code> — exists in <code>@soma/ui</code>; the chat composer hasn&#39;t been touched to include it. Trivial drop-in when the ACP backend list is ready.</li></ul><h3 id="tooling" tabindex="-1">Tooling <a class="header-anchor" href="#tooling" aria-label="Permalink to &quot;Tooling&quot;">​</a></h3><ul><li><s><strong><code>@soma/editor</code> typecheck broken on <code>main</code></strong> — <code>tsc --noEmit -p tsconfig.json</code> fails with <code>error TS2209: The project root is ambiguous</code>. Predates this revamp; surfaced because cutovers 5a–5e all touched the package. Workaround: typecheck via the soma renderer, which transitively type-checks the editor.</s> <strong>Fixed in <a href="https://github.com/stephane-segning/soma/pull/83" target="_blank" rel="noreferrer">#83</a></strong> — <code>tsconfig.json</code> gained <code>&quot;rootDir&quot;: &quot;./src&quot;</code> and dropped the <code>@soma/ui/*</code> path alias (which was forcing tsc to treat <code>desktop-ui/src/**</code> as in-package source). Workspace resolution at runtime is unchanged; the alias was only there for IDE jump-to-definition.</li><li><s><strong><code>@soma/editor</code> storybook</strong> — broken per earlier session notes (path-resolution error). Wave-4-and-after work was verified via @soma/ui&#39;s storybook + soma&#39;s typecheck instead. Storybook stories for the editor exist (<code>document-editor.stories.tsx</code>, <code>node-ai-registry.stories.tsx</code>) and would be the cheapest way to add interactive smoke coverage once the build is healthy.</s> <strong>Fixed in <a href="https://github.com/stephane-segning/soma/pull/94" target="_blank" rel="noreferrer">#94</a></strong> — a typo (<code>desktp-ui</code> → <code>desktop-ui</code>) in <code>.storybook/storybook.css</code> caused the PostCSS <code>@import</code> to fail. Two-line fix; <code>pnpm --filter @soma/editor run build:storybook</code> now completes successfully (7.6 MB <code>storybook-static/</code>).</li></ul><h2 id="the-testing-gap" tabindex="-1">The testing gap <a class="header-anchor" href="#the-testing-gap" aria-label="Permalink to &quot;The testing gap&quot;">​</a></h2><p><strong>None of the ten cutover PRs ship new automated tests.</strong> That&#39;s the single biggest risk in this body of work, and it&#39;s deliberate to call out rather than bury.</p><p>What we relied on:</p><ol><li><strong><code>tsc --noEmit</code></strong> — caught every signature mismatch and every breaking-change ripple through the workspace (e.g. the <code>EditorCommand.section</code> field migration in 5b).</li><li><strong>Storybook for <code>@soma/ui</code></strong> — visual sanity for the locked components in isolation, on their own catalog. Doesn&#39;t exercise the renderer wiring.</li><li><strong>Code review (Gemini code-review bot)</strong> — caught several real bugs, including the unit-mismatch P0 in 1b and the listener-churn perf issue in 5c. Helpful, but not a substitute for tests.</li></ol><p>What we don&#39;t have:</p><ul><li><strong>No unit tests</strong> for the new hooks (<code>use-space-bots</code>, <code>useSpaceAccessSettings</code>, <code>useWorkspaceAgentSettings</code>), the AI registry factory (<code>createDefaultAIRegistry</code>), the renderer-side <code>SpacesController.issueIssuerCapability</code>, or the IPC handler in <code>space-handlers.ts</code>. Regressions here are silent until a user trips them.</li><li><strong>No integration tests</strong> for the IPC boundary. The unit-mismatch bug in 1b would have been caught by a single test that issued a capability and read back the stored <code>expires_at</code> — none exists.</li><li><strong>No E2E / smoke tests</strong> of the renderer. Each cutover PR&#39;s &quot;test plan&quot; was a manual checklist that nobody ran.</li><li><strong>No regression coverage</strong> for the @soma/ui surfaces themselves. The <code>captureScope</code> prop, the icon-slot reservation, the ref-pattern fix to MentionPicker, the <code>onQueryChange</code> prop on CommandPalette — all locked-in via type signatures, none via assertions.</li></ul><h3 id="what-s-most-worth-adding-first" tabindex="-1">What&#39;s most worth adding first <a class="header-anchor" href="#what-s-most-worth-adding-first" aria-label="Permalink to &quot;What&#39;s most worth adding first&quot;">​</a></h3><p>Triaged by risk × cost:</p><ol><li><strong>IPC boundary contract tests</strong> for <code>spaces_issue_issuer_capability</code>, <code>spaces_list_members</code>, <code>spaces_decide_join</code> — main process plus a thin renderer-service test that mocks <code>invoke</code>. The unit-mismatch bug template is here.</li><li><strong>Hook tests</strong> for <code>use-space-bots</code> using <code>@testing-library/react</code> — covers form-to-mutation translation including the no-expiry path, future-date validation, and the spaceId-missing case.</li><li><strong>Registry-action tests</strong> for <code>createDefaultAIRegistry</code> — register, resolve by node type, dispatch explain/expand and assert insertion at the right range. Mocks the editor handle.</li><li><strong>Smoke storybook stories</strong> for each renderer wrapper (<code>SpacesRail</code>, <code>JumpToPageButton</code>, <code>CommandPaletteShell</code>, <code>BotsTab</code>) once the storybook config is healthy.</li></ol><p>A reasonable target before the next round of feature work: ~20–30 tests covering the four areas above. Most are small. The work is more about choosing the testing harness (vitest plus testing-library is already in the soma <code>devDependencies</code>) and writing the first one than about volume.</p><blockquote><p><strong>Update (post-#82):</strong> the test infrastructure landed in <a href="https://github.com/stephane-segning/soma/pull/82" target="_blank" rel="noreferrer">#82</a> — vitest + <code>@vitest/coverage-v8</code> on <code>@soma/ui</code> and the soma renderer, <code>@storybook/react</code> portable-stories wired through <code>setProjectAnnotations</code>, and a Cucumber × Playwright (<code>playwright-bdd</code>) E2E package targeting the same Storybook artifact we publish to gh-pages. Seed tests cover items 1–2 from the triage above (IPC contract for <code>issueIssuerCapability</code>, hook tests for <code>useSpaceBots</code>). Items 3–4 (NodeAIRegistry actions, renderer-wrapper smoke stories) remain open follow-ups now that the harness is in place. See <a href="./../../development/testing">Testing</a> for the running surfaces.</p></blockquote><blockquote><p><strong>Update (final):</strong> all four triage items above are now substantially addressed:</p><ol><li><strong>IPC boundary contract tests</strong> — <a href="https://github.com/stephane-segning/soma/pull/82" target="_blank" rel="noreferrer">#82</a> added <code>daemon-client.test.ts</code> (the test template that would have caught the cutover-1b unit-mismatch P0) + <code>spaces-service.integration.test.ts</code>. Subsequent PRs extended both for alias (<a href="https://github.com/stephane-segning/soma/pull/85" target="_blank" rel="noreferrer">#85</a>), status (<a href="https://github.com/stephane-segning/soma/pull/86" target="_blank" rel="noreferrer">#86</a>), <code>listSpaceBots</code> (<a href="https://github.com/stephane-segning/soma/pull/84" target="_blank" rel="noreferrer">#84</a>), and scopes (<a href="https://github.com/stephane-segning/soma/pull/92" target="_blank" rel="noreferrer">#92</a>).</li><li><strong>Hook tests for <code>use-space-bots</code></strong> — same PRs, plus the retry-button addition in <a href="https://github.com/stephane-segning/soma/pull/90" target="_blank" rel="noreferrer">#90</a>.</li><li><strong>Registry-action tests for <code>createDefaultAIRegistry</code></strong> — landed in <a href="https://github.com/stephane-segning/soma/pull/83" target="_blank" rel="noreferrer">#83</a> (13 tests) and extended in <a href="https://github.com/stephane-segning/soma/pull/95" target="_blank" rel="noreferrer">#95</a> when block-level dispatch was added.</li><li><strong>Smoke tests for renderer wrappers</strong> — <a href="https://github.com/stephane-segning/soma/pull/91" target="_blank" rel="noreferrer">#91</a> shipped 18 vitest+RTL render tests covering <code>SpacesRail</code>, <code>JumpToPageButton</code>, <code>CommandPaletteShell</code>, <code>BotsTab</code>. Implemented as vitest + jsdom (not Storybook stories) so they can mock the soma-specific RTK Query / i18n / IPC dependencies that don&#39;t have @soma/ui-side equivalents.</li></ol><p>CI gating: <a href="https://github.com/stephane-segning/soma/pull/89" target="_blank" rel="noreferrer">#89</a> added a <code>cargo build --workspace --locked</code> + <code>cargo test --workspace --locked</code> job to <code>.github/workflows/test.yml</code> (the napi-scoped <code>pnpm typecheck:node</code> was missing <code>somad</code>-binary build coverage, a gap that bit on #85). The repo now has Rust workspace + TS workspace + UI E2E gates on every PR.</p></blockquote><h2 id="pointers" tabindex="-1">Pointers <a class="header-anchor" href="#pointers" aria-label="Permalink to &quot;Pointers&quot;">​</a></h2><ul><li>Locked PRD: <a href="./ui-revamp-v0"><code>ui-revamp-v0.md</code></a></li><li>ADR with the locked decisions: <a href="./../adrs/0005-ui-revamp-v0"><code>../adrs/0005-ui-revamp-v0.md</code></a></li><li>Build waves + acceptance criteria: <a href="./ui-revamp-v0-scaffold"><code>ui-revamp-v0-scaffold.md</code></a></li><li>Per-flow refs: <code>ui-revamp-v0-refs-*.md</code> siblings</li><li><code>@soma/ui</code> package: <code>desktop/desktop-ui/src/components/</code></li><li><code>@soma/editor</code> package: <code>desktop/desktop-editor/src/</code></li><li>Soma renderer: <code>desktop/soma/src/renderer/src/</code></li><li>Main process IPC handlers: <code>desktop/soma/src/main/command-registry/</code></li></ul>',31)])])}const g=o(r,[["render",d]]);export{u as __pageData,g as default};
